"""Hash-fenced FP4 index-key temporary-memory reduction; no cache mutation."""
import sys
if sys.flags.optimize or not __debug__:
    raise RuntimeError('Qualification helpers require unoptimized Python')
import ast,hashlib,sys
from pathlib import Path
SOURCE_SHA256='cb118c1cd0ba11a7ea216242e485d6098162984e6e21df3b40b5248b320af190'
OUTPUT_SHA256='61d6b6b4e535e849b772b4e71e3823e7d5186eda9a3a66613b993f6b36da25d8'
ANCHOR='        u = buf[page, payload_cols].view(torch.uint8)  # [n, 64]\n        codes = torch.stack([u & 0x0F, (u >> 4) & 0x0F], dim=-1)  # [n, 64, 2]\n        vals = DSV4_DEQUANT_FP4_TABLE.to(buf.device)[codes.long()].flatten(\n            1\n        )  # [n, 128]\n        exps = buf[page, scale_cols].to(torch.int32) & 0xFF  # [n, 4]\n        scales = torch.exp2(exps.float() - 127).repeat_interleave(32, dim=-1)\n        return (vals * scales).to(torch.bfloat16)\n'
REPLACEMENT='        u = buf[page, payload_cols].view(torch.uint8)  # [n, 64]\n        del payload_cols\n        exps = buf[page, scale_cols].to(torch.int32) & 0xFF  # [n, 4]\n        del page, off, scale_cols\n        codes = torch.stack([u & 0x0F, (u >> 4) & 0x0F], dim=-1)\n        del u\n        # FP4 codes are 0..15; int32 indices avoid an unnecessary int64 table.\n        vals = torch.index_select(\n            DSV4_DEQUANT_FP4_TABLE.to(buf.device), 0,\n            codes.flatten().to(torch.int32),\n        ).view(-1, 128)\n        del codes\n        scales = torch.exp2(exps.float() - 127)\n        del exps\n        if not vals.requires_grad and vals.dtype == scales.dtype:\n            # Lookup owns this tensor. Broadcast four scales without expanding128.\n            vals.view(-1, 4, 32).mul_(scales.unsqueeze(-1))\n            return vals.to(torch.bfloat16)\n        return (vals * scales.repeat_interleave(32, dim=-1)).to(torch.bfloat16)\n'
def patch(source):
    if hashlib.sha256(source.encode()).hexdigest()!=SOURCE_SHA256 or source.count(ANCHOR)!=1:
        raise ValueError('Unknown FP4 pool source; refuse overlay')
    result=source.replace(ANCHOR,REPLACEMENT,1);ast.parse(result);return result
if __name__=='__main__':
    source,output=map(Path,sys.argv[1:]);assert not output.exists(),'Preserve existing overlay'
    result=patch(source.read_text(encoding='utf-8')).encode()
    assert hashlib.sha256(result).hexdigest()==OUTPUT_SHA256,'Generated bytes differ; refuse before startup'
    output.write_bytes(result)
